setcpm(90/4)

// Odd bars: the body preset. Even bars: the rendered cavity proposed to replace it
// One click marks a preset bar, two clicks a rendered bar
const phrase = note("<[e3 g3 b3 e4 b3 g3] [e3 g3 b3 e4 b3 g3] [d3 a3 d4 f#4 d4 a3] [d3 a3 d4 f#4 d4 a3]>")
const pluck = (x) => x.s("triangle").attack(.002).decay(.4).sustain(0).release(.3)

preset: phrase.pluck().body("guitar").mask("<1 0>").gain(.4)
rendered: phrase.pluck().cavity("box").cavsize(.45).material("spruce").cavhole(.3).mask("<0 1>").gain(.4)
marker: s("<[click ~ ~ ~] [click click ~ ~]>").hpf(3000).gain(.08)

setcpm(72/4)

// Odd bars: the body preset. Even bars: the rendered cavity proposed to replace it
const phrase = note("<[a4@3 c5 e5@4] [a4@3 c5 e5@4] [d5@2 c5 b4 a4@4] [d5@2 c5 b4 a4@4]>")
const bowed = (x) => x.s("sawtooth").vib(5.5).vibdepth(.12).attack(.08).sustain(.75).release(.3).lpf(3600)

preset: phrase.bowed().body("violin").mask("<1 0>").gain(.22)
rendered: phrase.bowed().cavity("box").cavsize(.35).cavratio(.4).material("maple").cavhole(.1).mask("<0 1>").gain(.22)
marker: s("<[click ~ ~ ~] [click click ~ ~]>").hpf(3000).gain(.08)

setcpm(96/4)

// Odd bars: the body preset. Even bars: the rendered cavity proposed to replace it
const kit = s("<[bd rim sd rim] [bd rim sd rim] [bd [rim rim] sd lt] [bd [rim rim] sd lt]>")
const tune = note("<[c4 e4 g4 e4] [c4 e4 g4 e4] [a3 c4 e4 c4] [a3 c4 e4 c4]>").s("triangle").decay(.3).sustain(0)

preset: stack(kit, tune).body("box").mask("<1 0>").gain(.4)
rendered: stack(kit, tune).cavity("box").cavsize(.95).cavratio(.5).material("wood").mask("<0 1>").gain(.4)
marker: s("<[click ~ ~ ~] [click click ~ ~]>").hpf(3000).gain(.08)

setcpm(80/4)

// Odd bars: the body preset. Even bars: the rendered cavity proposed to replace it
const phrase = note("<[a2 e3 a3 e3] [a2 e3 a3 e3] [g2 d3 g3 d3] [g2 d3 g3 d3]>")
const blow = (x) => x.s("sawtooth").attack(.02).decay(.3).sustain(.3).release(.2).lpf(2400)

preset: phrase.blow().body("tube").mask("<1 0>").gain(.25)
rendered: phrase.blow().cavity("tube").cavsize(.78).cavratio(.15).material("plastic").mask("<0 1>").gain(.25)
marker: s("<[click ~ ~ ~] [click click ~ ~]>").hpf(3000).gain(.08)

setcpm(100/4)

// Odd bars: the body preset. Even bars: the rendered cavity proposed to replace it
const kit = s("<[cp rim hh rim] [cp rim hh rim] [rim cp [rim rim] hh] [rim cp [rim rim] hh]>")

preset: kit.body("can").mask("<1 0>").gain(.4)
rendered: kit.cavity("cylinder").cavsize(.32).cavratio(.6).material("metal").cavhole(.5).mask("<0 1>").gain(.4)
marker: s("<[click ~ ~ ~] [click click ~ ~]>").hpf(3000).gain(.08)

setcpm(84/4)

// Odd bars: the body preset. Even bars: the rendered cavity proposed to replace it
const phrase = note("<[c4 d4 e4 g4] [c4 d4 e4 g4] [a4 g4 e4 d4] [a4 g4 e4 d4]>")
const sing = (x) => x.s("voice").syl("la li lo la").voicetype("alto").mono(1).vglide(.06).release(.3)

preset: phrase.sing().body("phone").mask("<1 0>").gain(.3)
rendered: phrase.sing().cavity("box").cavsize(.12).cavratio(.5).material("plastic").cavhole(.2).mask("<0 1>").gain(.3)
marker: s("<[click ~ ~ ~] [click click ~ ~]>").hpf(3000).gain(.08)

setcpm(88/4)

// Odd bars: the body preset. Even bars: the rendered cavity proposed to replace it
const chords = note("<[c3,e3,g3] [c3,e3,g3] [a2,c3,e3] [a2,c3,e3]>").struct("x ~ x x")
const keys = (x) => x.s("sawtooth").decay(.3).sustain(.2).release(.2).lpf(3000)

preset: chords.keys().body("radio").mask("<1 0>").gain(.22)
rendered: chords.keys().cavity("box").cavsize(.3).cavratio(.6).material("wood").cavhole(.5).mask("<0 1>").gain(.22)
marker: s("<[click ~ ~ ~] [click click ~ ~]>").hpf(3000).gain(.08)

setcpm(96/4)

// Odd bars: the body preset. Even bars: the rendered cavity proposed to replace it
const phrase = note("<[g3 g3 c4 g3] [g3 g3 c4 g3] [a3 g3 e3 ~] [a3 g3 e3 ~]>")
const shout = (x) => x.s("voice").syl("hey ho let go").voicetype("tenor").effort(1).release(.2)

preset: phrase.shout().body("megaphone").mask("<1 0>").gain(.3)
rendered: phrase.shout().cavity("tube").cavsize(.4).cavratio(.4).material("metal").mask("<0 1>").gain(.3)
marker: s("<[click ~ ~ ~] [click click ~ ~]>").hpf(3000).gain(.08)

setcpm(90/4)

// Odd bars: the body preset. Even bars: the rendered cavity, each two bars at a matching size
const phrase = note("e3 g3 b3 e4 b3 g3")
const pluck = (x) => x.s("triangle").attack(.002).decay(.4).sustain(0).release(.3)

preset: phrase.pluck().body("guitar").bodysize("<.5 .5 1 1 2 2>").mask("<1 0>").gain(.4)
rendered: phrase.pluck().cavity("box").cavsize("<.225 .225 .45 .45 .9 .9>").material("spruce").cavhole(.3)
  .mask("<0 1>").gain(.4)
marker: s("<[click ~ ~ ~] [click click ~ ~]>").hpf(3000).gain(.08)

setcpm(90/4)

// Odd bars: the guitar preset. Even bars: the box in spruce, maple, wood, then plastic
const phrase = note("e3 g3 b3 e4 b3 g3")
const pluck = (x) => x.s("triangle").attack(.002).decay(.4).sustain(0).release(.3)

preset: phrase.pluck().body("guitar").mask("<1 0>").gain(.4)
rendered: phrase.pluck().cavity("box").cavsize(.45).cavhole(.3)
  .material("<spruce spruce maple maple wood wood plastic plastic>").mask("<0 1>").gain(.4)
marker: s("<[click ~ ~ ~] [click click ~ ~]>").hpf(3000).gain(.08)

setcpm(90/4)

// Odd bars: the body preset at half mix. Even bars: the rendered cavity at half mix
const phrase = note("<[e3 g3 b3 e4 b3 g3] [e3 g3 b3 e4 b3 g3] [c3 g3 c4 e4 c4 g3] [c3 g3 c4 e4 c4 g3]>")
const pluck = (x) => x.s("triangle").attack(.002).decay(.4).sustain(0).release(.3)

preset: phrase.pluck().body("guitar").bodymix(.5).mask("<1 0>").gain(.4)
rendered: phrase.pluck().cavity("box").cavsize(.45).material("spruce").cavhole(.3).cavmix(.5).mask("<0 1>").gain(.4)
marker: s("<[click ~ ~ ~] [click click ~ ~]>").hpf(3000).gain(.08)

setcpm(90/4)

// Odd bars: body and cavity on one track. The checker warns, and only the cavity should sound
// Even bars: the body preset alone, for reference. Odd and even bars should sound different
const phrase = note("e3 g3 b3 e4 b3 g3")
const pluck = (x) => x.s("triangle").attack(.002).decay(.4).sustain(0).release(.3)

both: phrase.pluck().body("can").cavity("box").cavsize(.45).material("spruce").cavhole(.3).mask("<1 0>").gain(.4)
bodyonly: phrase.pluck().body("can").mask("<0 1>").gain(.4)
marker: s("<[click ~ ~ ~] [click click ~ ~]>").hpf(3000).gain(.08)
